from __future__ import annotations

from html import escape

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse, RedirectResponse

from .branding import ENDORSEMENT, PRODUCT_FULL_NAME, TAGLINE

router = APIRouter()

CSS = r"""
:root{--bg:#020309;--side:#060812;--panel:#0a0e1b;--panel2:#11172a;--line:#ffffff19;--text:#f6f7ff;--muted:#a9b2c8;--gold:#edcc73;--violet:#9b70ff;--cyan:#58dfff;--green:#73e2aa;--red:#ff8fa6}*{box-sizing:border-box}html,body{margin:0;height:100%;background:radial-gradient(circle at 7% 0,#40186a55,transparent 26%),radial-gradient(circle at 96% 0,#123c7655,transparent 24%),var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer;color:inherit}.layout{height:100vh;display:grid;grid-template-columns:300px minmax(0,1fr)}.sidebar{min-height:0;background:#050711ef;border-right:1px solid var(--line);display:flex;flex-direction:column}.sideHead{padding:14px;border-bottom:1px solid var(--line)}.brand{font-size:1.05rem;font-weight:950}.brand small{display:block;color:var(--gold);font-size:.63rem;letter-spacing:.1em;text-transform:uppercase;margin-top:3px}.btn{border:1px solid var(--line);background:#ffffff07;border-radius:11px;padding:9px 11px;font-weight:800}.btn:hover{background:#ffffff10}.primary{border:0;background:linear-gradient(115deg,var(--gold),var(--violet));color:#160d1d}.new{width:100%;margin-top:12px}.search,.select{width:100%;border:1px solid var(--line);background:#080b16;color:#fff;border-radius:10px;padding:9px;outline:0}.search{margin-top:9px}.threads{flex:1;overflow:auto;padding:8px}.thread{padding:9px;border:1px solid transparent;border-radius:11px;margin:3px 0;cursor:pointer}.thread:hover,.thread.active{background:#ffffff09;border-color:var(--line)}.thread b{display:block;font-size:.86rem;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.thread small{font-size:.69rem;color:var(--muted)}.sideFoot{border-top:1px solid var(--line);padding:10px;display:grid;gap:7px}.main{height:100vh;display:flex;flex-direction:column;min-width:0}.top{min-height:68px;border-bottom:1px solid var(--line);background:#050711dc;backdrop-filter:blur(18px);display:flex;align-items:center;gap:8px;padding:9px 14px;flex-wrap:wrap}.title{font-weight:950;margin-right:auto;min-width:160px}.title small{display:block;color:var(--muted);font-size:.68rem;font-weight:600}.top select{width:min(260px,34vw)}.toggle{border:1px solid var(--line);border-radius:10px;padding:7px 8px;display:flex;align-items:center;gap:5px;font-size:.75rem;background:#ffffff04}.chat{flex:1;overflow:auto;padding:25px 16px 170px}.conversation{width:min(920px,100%);margin:auto}.empty{text-align:center;padding:100px 20px;color:var(--muted)}.empty h1{color:#fff;font-size:clamp(2rem,6vw,4.5rem);line-height:.96;letter-spacing:-.05em;margin:.2em 0}.msg{margin:19px 0}.msg.user{display:flex;justify-content:flex-end}.bubble{max-width:86%;border-radius:18px;padding:13px 15px;line-height:1.6;overflow-wrap:anywhere}.user .bubble{background:linear-gradient(145deg,#2a1d4e,#152540);border:1px solid #9b70ff42}.assistant .bubble{max-width:100%;padding-left:0;padding-right:0}.attachments{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:7px}.chip{border:1px solid var(--line);border-radius:10px;padding:6px 8px;color:var(--muted);font-size:.71rem;background:#ffffff04}.actions{display:flex;gap:3px;flex-wrap:wrap;margin-top:6px;opacity:.72}.mini{border:0;background:transparent;color:var(--muted);padding:4px 6px;border-radius:7px;font-size:.7rem}.mini:hover{background:#ffffff0c;color:#fff}.toolLine{color:var(--green);font-size:.72rem;margin:5px 0}.thinking{color:var(--muted);font-size:.78rem;display:flex;align-items:center;gap:6px}.dot{width:6px;height:6px;border-radius:50%;background:var(--violet);animation:pulse 1s infinite alternate}@keyframes pulse{to{transform:scale(1.8);opacity:.45}}pre{white-space:pre-wrap;background:#070a12;border:1px solid var(--line);border-radius:11px;padding:11px;overflow:auto}code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.composerWrap{position:fixed;left:300px;right:0;bottom:0;padding:18px;background:linear-gradient(transparent,#020309 30%)}.composer{width:min(940px,100%);margin:auto;background:#0a0e1bf3;border:1px solid #ffffff27;border-radius:20px;box-shadow:0 15px 55px #0009;padding:8px}.pending{display:flex;gap:6px;flex-wrap:wrap;padding:2px 4px}.composeRow{display:flex;align-items:flex-end;gap:7px}.composeRow textarea{flex:1;min-height:48px;max-height:190px;resize:none;border:0;outline:0;background:transparent;color:#fff;line-height:1.45;padding:11px}.round{width:42px;height:42px;flex:0 0 42px;border-radius:50%;border:1px solid var(--line);background:#ffffff08;font-weight:900}.send{border:0;background:linear-gradient(115deg,var(--gold),var(--violet));color:#160d1d}.stop{background:#4b1b2a;border-color:#ff8fa655}.notice{position:fixed;right:16px;top:78px;max-width:420px;z-index:60;border:1px solid var(--line);background:#12172a;border-radius:12px;padding:10px 12px;display:none}.notice.show{display:block}.drawer{position:fixed;right:0;top:0;bottom:0;width:min(440px,100%);background:#080c18fa;border-left:1px solid var(--line);z-index:70;transform:translateX(105%);transition:.2s;padding:16px;overflow:auto}.drawer.open{transform:translateX(0)}.mem{border:1px solid var(--line);border-radius:12px;padding:10px;margin:8px 0;background:#ffffff05}.muted{color:var(--muted)}.mobile{display:none}@media(max-width:820px){.layout{grid-template-columns:1fr}.sidebar{position:fixed;left:0;top:0;bottom:0;width:min(310px,90vw);z-index:80;transform:translateX(-105%);transition:.2s}.sidebar.open{transform:translateX(0)}.composerWrap{left:0}.mobile{display:inline-block}.top select{width:min(220px,60vw)}.bubble{max-width:96%}}
"""

SCRIPT = r"""
const A='/aura-intelligence/api';let current=null,threads=[],projects=[],pending=[],messagesCache=[],controller=null,recording=false,recorder=null,chunks=[];const $=id=>document.getElementById(id);function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function markdown(v){let x=esc(v),blocks=[];x=x.replace(/```([\s\S]*?)```/g,(m,c)=>{const i=blocks.push(`<pre><code>${c.trim()}</code></pre>`)-1;return `@@C${i}@@`});x=x.replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<b>$1</b>').replace(/^### (.+)$/gm,'<h3>$1</h3>').replace(/^## (.+)$/gm,'<h2>$1</h2>').replace(/^# (.+)$/gm,'<h1>$1</h1>').replace(/\n/g,'<br>');blocks.forEach((b,i)=>x=x.replace(`@@C${i}@@`,b));return x}function note(m,b=false){const n=$('notice');n.textContent=m;n.style.borderColor=b?'#ff8fa655':'';n.className='notice show';clearTimeout(window._n);window._n=setTimeout(()=>n.className='notice',5000)}function fmt(n){n=Number(n||0);if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';return(n/1048576).toFixed(1)+' MB'}async function req(u,o={}){const r=await fetch(u,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(o.headers||{})},...o});let b={};try{b=await r.json()}catch(e){}if(!r.ok)throw new Error(b.detail||`Request failed (${r.status})`);return b}
async function boot(){try{const[t,p,s]=await Promise.all([req(A+'/threads'),req(A+'/projects'),req(A+'/status')]);threads=t;projects=p;renderThreads();renderProjects();$('status').textContent=`${s.model?.provider_mode||'Aura'} · ${s.web?.search_configured?'web ready':'local web'} · streaming`;if(threads.length)await openThread(threads[0].id);else await newThread()}catch(e){note(e.message,true)}}function renderThreads(){const q=($('search').value||'').toLowerCase();$('threads').innerHTML=threads.filter(t=>!q||String(t.title).toLowerCase().includes(q)).map(t=>`<div class="thread ${t.id===current?'active':''}" data-thread="${t.id}"><b>${esc(t.title)}</b><small>${t.project_name?'📌 '+esc(t.project_name)+' · ':''}${t.message_count||0} messages</small></div>`).join('')||'<div class="empty">No conversations</div>';document.querySelectorAll('[data-thread]').forEach(el=>el.onclick=()=>openThread(el.dataset.thread))}function renderProjects(){$('project').innerHTML='<option value="">No project pinned</option>'+projects.map(p=>`<option value="${esc(p.project_name)}">${esc(p.title)} · ${esc(p.project_name)}</option>`).join('')}async function refreshThreads(q=''){threads=await req(A+'/threads'+(q?'?q='+encodeURIComponent(q):''));renderThreads()}async function newThread(){const t=await req(A+'/threads',{method:'POST',body:'{}'});await refreshThreads();await openThread(t.id);$('sidebar').classList.remove('open')}async function openThread(id){if(controller)return note('Stop the current response before switching conversations.',true);current=id;const d=await req(`${A}/threads/${id}`);messagesCache=d.messages||[];renderThread(d);renderThreads();$('sidebar').classList.remove('open')}
function actions(m){return m.role==='assistant'?`<button class="mini" data-action="copy" data-id="${m.id}">Copy</button><button class="mini" data-action="regen" data-id="${m.id}">Regenerate</button><button class="mini" data-action="speak" data-id="${m.id}">🔊 Speak</button><button class="mini" data-action="branch" data-id="${m.id}">Branch</button>`:`<button class="mini" data-action="edit" data-id="${m.id}">Edit</button><button class="mini" data-action="branch" data-id="${m.id}">Branch</button>`}function messageHTML(m,tools=[]){const at=(m.attachments||[]).map(a=>`<span class="chip">📎 ${esc(a.name)} · ${fmt(a.bytes)}</span>`).join('');const tool=tools.map(t=>`<span>${t.status==='completed'?'✓':'!'} ${esc(t.tool_name)}</span>`).join(' · ');return `<div class="msg ${m.role}" data-message="${m.id}"><div class="bubble">${at?`<div class="attachments">${at}</div>`:''}<div class="body">${markdown(m.content)}</div>${tool?`<div class="toolLine">Aura tools: ${tool}</div>`:''}<div class="actions">${actions(m)}</div></div></div>`}function bindActions(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>doAction(b.dataset.action,b.dataset.id))}function renderThread(d){$('chatTitle').textContent=d.thread.title;$('project').value=d.thread.project_name||'';$('web').checked=!!d.thread.web_enabled;$('tools').checked=!!d.thread.tools_enabled;const toolMap={};(d.tool_runs||[]).forEach(t=>{if(t.message_id)(toolMap[t.message_id]??=[]).push(t)});const c=$('conversation');if(!messagesCache.length)c.innerHTML=`<div class="empty"><div class="muted">PULSAR-FREQUENCY HOUSE</div><h1>What shall we create?</h1><p>Talk normally, pin a project, attach documents or media, research the web, or tell Aura to use a connected Studio tool.</p></div>`;else c.innerHTML=messagesCache.map(m=>messageHTML(m,toolMap[m.id]||[])).join('');bindActions();scrollBottom()}function scrollBottom(){setTimeout(()=>{$('chat').scrollTop=$('chat').scrollHeight},20)}
async function doAction(action,id){const m=messagesCache.find(x=>x.id===id);if(action==='copy'){await navigator.clipboard.writeText(m?.content||'');return note('Copied.')}if(action==='speak'){const audio=new Audio(`${A}/threads/${current}/messages/${id}/speech`);return audio.play().catch(()=>note('Aura speech output is not configured on this host.',true))}if(action==='branch'){try{const t=await req(`${A}/threads/${current}/branch/${id}`,{method:'POST',body:'{}'});await refreshThreads();await openThread(t.id);note('Conversation branched.')}catch(e){note(e.message,true)}return}if(action==='edit'){if(!m)return;const v=prompt('Edit your message:',m.content);if(v===null||!v.trim())return;try{await req(`${A}/threads/${current}/messages/${id}`,{method:'PATCH',body:JSON.stringify({message:v.trim()})});await refreshThreads();await openThread(current)}catch(e){note(e.message,true)}return}if(action==='regen'){try{showBusy('Regenerating Aura response…');await req(`${A}/threads/${current}/regenerate`,{method:'POST',body:'{}'});await refreshThreads();await openThread(current)}catch(e){note(e.message,true)}finally{hideBusy()}return}}
function optimisticUser(text,ids){const attachments=pending.filter(x=>ids.includes(x.id));const m={id:'local_'+Date.now(),role:'user',content:text,attachments};messagesCache.push(m);$('conversation').insertAdjacentHTML('beforeend',messageHTML(m,[]));bindActions();scrollBottom()}function createStreamingBubble(){const id='stream_'+Date.now();$('conversation').insertAdjacentHTML('beforeend',`<div class="msg assistant" id="${id}"><div class="bubble"><div class="thinking" id="${id}_status"><span class="dot"></span><span>Aura is thinking…</span></div><div class="body" id="${id}_body"></div><div class="toolLine" id="${id}_tools"></div></div></div>`);scrollBottom();return id}async function send(text=null){if(!current||controller)return;const box=$('composer'),msg=(text??box.value).trim();if(!msg)return;const ids=pending.map(x=>x.id);box.value='';optimisticUser(msg,ids);pending=[];renderPending();const sid=createStreamingBubble();controller=new AbortController();$('send').textContent='■';$('send').classList.add('stop');$('send').onclick=stop;let acc='',buffer='';try{const r=await fetch(`${A}/threads/${current}/messages-stream`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:msg,attachment_ids:ids}),signal:controller.signal});if(!r.ok){let e={};try{e=await r.json()}catch(_){}throw new Error(e.detail||`Request failed (${r.status})`)}const reader=r.body.getReader(),dec=new TextDecoder();while(true){const{value,done}=await reader.read();if(done)break;buffer+=dec.decode(value,{stream:true});let i;while((i=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,i).trim();buffer=buffer.slice(i+1);if(!line)continue;let ev;try{ev=JSON.parse(line)}catch(_){continue}if(ev.type==='start'){$(`${sid}_status`).querySelector('span:last-child').textContent='Aura is responding…'}else if(ev.type==='tool'){const t=$(`${sid}_tools`);t.textContent+=(t.textContent?' · ':'')+(ev.ok?'✓ ':'! ')+ev.name}else if(ev.type==='delta'){acc+=ev.text;$(`${sid}_body`).innerHTML=markdown(acc);scrollBottom()}else if(ev.type==='error'){throw new Error(ev.error||'Aura generation failed')}else if(ev.type==='done'){$(`${sid}_status`).remove();await refreshThreads()}}}await openThread(current)}catch(e){if(e.name==='AbortError')note('Aura generation stopped.');else{note(e.message,true);const s=$(`${sid}_status`);if(s)s.innerHTML='<span>Generation stopped with an error.</span>'}}finally{controller=null;$('send').textContent='↑';$('send').classList.remove('stop');$('send').onclick=()=>send();box.focus()}}function stop(){if(controller)controller.abort()}function keysend(e){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}}function showBusy(t){const id=createStreamingBubble();window._busy=id;$(`${id}_status`).querySelector('span:last-child').textContent=t}function hideBusy(){if(window._busy){document.getElementById(window._busy)?.remove();window._busy=null}}
async function setContext(){if(!current)return;try{await req(`${A}/threads/${current}`,{method:'PATCH',body:JSON.stringify({project_name:$('project').value,clear_project:!$('project').value,web_enabled:$('web').checked,tools_enabled:$('tools').checked})});await refreshThreads();note('Aura context updated.')}catch(e){note(e.message,true)}}async function renameThread(){const t=threads.find(x=>x.id===current),v=prompt('Conversation title:',t?.title||'');if(!v)return;try{await req(`${A}/threads/${current}`,{method:'PATCH',body:JSON.stringify({title:v})});await refreshThreads();$('chatTitle').textContent=v}catch(e){note(e.message,true)}}async function deleteThread(){if(!current||!confirm('Delete this Aura conversation?'))return;try{await req(`${A}/threads/${current}`,{method:'DELETE'});current=null;await refreshThreads();threads.length?openThread(threads[0].id):newThread()}catch(e){note(e.message,true)}}
async function uploadFiles(files){if(!current)return;for(const file of files){const fd=new FormData();fd.append('file',file);try{const r=await fetch(`${A}/threads/${current}/attachments`,{method:'POST',credentials:'same-origin',body:fd});const b=await r.json();if(!r.ok)throw new Error(b.detail||'Upload failed');pending.push(b);renderPending()}catch(e){note(e.message,true)}}$('file').value=''}function renderPending(){$('pending').innerHTML=pending.map((a,i)=>`<span class="chip">📎 ${esc(a.name)} <button class="mini" data-remove="${i}">×</button></span>`).join('');document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{pending.splice(Number(b.dataset.remove),1);renderPending()})}
async function mic(){if(recording){recorder.stop();return}if(!navigator.mediaDevices?.getUserMedia)return note('Microphone capture is not available here.',true);try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=async()=>{recording=false;$('mic').textContent='🎙';stream.getTracks().forEach(t=>t.stop());const fd=new FormData();fd.append('file',new Blob(chunks,{type:recorder.mimeType||'audio/webm'}),'aura-voice.webm');try{$('mic').textContent='…';const r=await fetch(`${A}/threads/${current}/voice-transcribe`,{method:'POST',credentials:'same-origin',body:fd});const b=await r.json();if(!r.ok)throw new Error(b.detail||'Transcription failed');$('composer').value=b.transcript;await send(b.transcript)}catch(e){note(e.message,true)}finally{$('mic').textContent='🎙'}};recorder.start();recording=true;$('mic').textContent='■'}catch(e){note('Microphone permission was not granted.',true)}}
async function openMemory(){$('memory').classList.add('open');await loadMemory()}async function loadMemory(){try{const rows=await req(A+'/memories');$('memoryRows').innerHTML=rows.map(x=>`<div class="mem"><b>${esc(x.label)}</b><p>${esc(x.content)}</p><button class="mini" data-forget="${x.id}">Delete memory</button></div>`).join('')||'<p class="muted">No saved Aura memories. Ordinary chat is not silently copied here.</p>';document.querySelectorAll('[data-forget]').forEach(b=>b.onclick=()=>forget(b.dataset.forget))}catch(e){note(e.message,true)}}async function saveMemory(){const v=$('memText').value.trim();if(!v)return;try{await req(A+'/memories',{method:'POST',body:JSON.stringify({label:$('memLabel').value||'Memory',content:v})});$('memText').value='';await loadMemory()}catch(e){note(e.message,true)}}async function forget(id){if(!confirm('Delete this saved memory?'))return;await req(`${A}/memories/${id}`,{method:'DELETE'});await loadMemory()}function side(){$('sidebar').classList.toggle('open')}$('search').addEventListener('input',()=>{clearTimeout(window._sq);window._sq=setTimeout(()=>refreshThreads($('search').value.trim()),250)});boot();
"""


@router.get("/aura-intelligence", response_class=HTMLResponse, include_in_schema=False)
def aura_realtime_page(request: Request):
    member = getattr(request.state, "member", None)
    if member is None:
        return RedirectResponse("/signin?next=/aura-intelligence", status_code=303)
    html = f"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='robots' content='noindex,nofollow'><title>Aura — {escape(PRODUCT_FULL_NAME)}</title><style>{CSS}</style></head><body><div class='layout'><aside class='sidebar' id='sidebar'><div class='sideHead'><div class='brand'>Aura<small>{escape(PRODUCT_FULL_NAME)}</small></div><button class='btn primary new' onclick='newThread()'>＋ New conversation</button><input class='search' id='search' placeholder='Search conversations'></div><div class='threads' id='threads'></div><div class='sideFoot'><button class='btn' onclick='openMemory()'>🧠 Aura Memory</button><a class='btn' href='/dashboard' style='text-decoration:none;text-align:center'>← Dashboard</a></div></aside><main class='main'><header class='top'><button class='btn mobile' onclick='side()'>☰</button><div class='title'><span id='chatTitle'>Aura</span><small id='status'>Loading Aura Core…</small></div><select class='select' id='project' onchange='setContext()'></select><label class='toggle'><input id='web' type='checkbox' onchange='setContext()'> Web</label><label class='toggle'><input id='tools' type='checkbox' onchange='setContext()'> Tools</label><button class='btn' onclick='renameThread()'>Rename</button><button class='btn' onclick='deleteThread()'>Delete</button></header><section class='chat' id='chat'><div class='conversation' id='conversation'></div></section><div class='composerWrap'><div class='composer'><div class='pending' id='pending'></div><div class='composeRow'><input id='file' type='file' multiple hidden onchange='uploadFiles(this.files)'><button class='round' onclick="$('file').click()" title='Attach files'>＋</button><button class='round' id='mic' onclick='mic()' title='Speak to Aura'>🎙</button><textarea id='composer' rows='1' placeholder='Message Aura…' onkeydown='keysend(event)'></textarea><button class='round send' id='send' onclick='send()'>↑</button></div></div></div></main></div><div class='notice' id='notice'></div><aside class='drawer' id='memory'><div style='display:flex;justify-content:space-between;align-items:center'><div><b>Aura Memory</b><div class='muted' style='font-size:.74rem'>Only facts you explicitly save are persistent memory.</div></div><button class='btn' onclick="$('memory').classList.remove('open')">×</button></div><input class='search' id='memLabel' placeholder='Memory label'><textarea class='search' id='memText' rows='4' placeholder='What should Aura remember?'></textarea><button class='btn primary' onclick='saveMemory()'>Save memory</button><div id='memoryRows'></div></aside><script>{SCRIPT}</script></body></html>"""
    return HTMLResponse(html)


__all__ = ["router"]
